 {
  "name": "prepare",
  "steps": [
   {
    "say": "prepare this for PETG, strong",
    "replies": [
     {
      "record": "prepare-petg-strong",
      "call": "setup_record",
      "arguments": {
       "purpose": "PETG, strong"
      }
     },
     {
      "record": "after-intent",
      "skill": "project-setup-changed",
      "call": "presets_list",
      "arguments": {
       "kind": "filament",
       "query": "PETG",
       "compatibleOnly": true
      }
     },
     {
      "call": "settings_get",
      "arguments": {
       "scope": "process",
       "keys": [
        "wall_loops",
        "sparse_infill_density",
        "sparse_infill_pattern",
        "top_shell_layers",
        "bottom_shell_layers"
       ]
      }
     },
     {
      "call": "setup_record",
      "arguments": {
       "purpose": "PETG, strong",
       "headline": "Switch to Bambu PETG HF and make the print stronger",
       "decisions": [
        {
         "topic": "filament",
         "statement": "Use Bambu PETG HF @BBL X1C"
        },
        {
         "topic": "strength",
         "statement": "4 walls and 25% gyroid infill"
        },
        {
         "topic": "plate",
         "statement": "Print on the Textured PEI Plate"
        }
       ],
       "unverified": [
        "The spool to be loaded is Bambu PETG HF."
       ]
      }
     },
     {
      "call": "printer_setup_preview",
      "arguments": {
       "filamentPresets": [
        "Bambu PETG HF @BBL X1C"
       ],
       "plateType": "Textured PEI Plate"
      }
     },
     {
      "call": "printer_setup",
      "arguments": {
       "filamentPresets": [
        "Bambu PETG HF @BBL X1C"
       ],
       "plateType": "Textured PEI Plate"
      }
     },
     {
      "call": "settings_preview_patch",
      "arguments": {
       "scope": "process",
       "changes": {
        "wall_loops": 4,
        "sparse_infill_density": "25%",
        "sparse_infill_pattern": "gyroid"
       }
